#include <bits/stdc++.h>
using namespace std;

vector<int> multiply(int x, const vector<int>& number) {
    vector<int> result;
    long long carry = 0;

    for (int digit : number) {
        long long product = 1LL * digit * x + carry;
        result.push_back(static_cast<int>(product % 10));
        carry = product / 10;
    }

    while (carry > 0) {
        result.push_back(static_cast<int>(carry % 10));
        carry /= 10;
    }

    return result;
}

vector<int> power(int x, int n) {
    if (n == 0) return {1};
    if (x == 0) return {0};

    vector<int> result = {1};

    for (int i = 0; i < n; ++i) {
        result = multiply(x, result);
    }

    while (result.size() > 1 && result.back() == 0) {
        result.pop_back();
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y;
    cin >> x >> y;

    vector<int> left = power(x, y);
    vector<int> right = power(y, x);

    if (left.size() != right.size()) {
        cout << (left.size() > right.size() ? ">\n" : "<\n");
        return 0;
    }

    for (int i = static_cast<int>(left.size()) - 1; i >= 0; --i) {
        if (left[i] != right[i]) {
            cout << (left[i] > right[i] ? ">\n" : "<\n");
            return 0;
        }
    }

    cout << "=\n";
    return 0;
}

