using namespace std;
using boost::multiprecision::cpp_int;

cpp_int power(cpp_int base, unsigned long long exponent) {
    cpp_int result = 1;
    while (exponent > 0) {
        if (exponent & 1ULL)
            result *= base;
        base *= base;
        exponent >>= 1ULL;
    }
    return result;
}

int main() {
    unsigned long long x, y;
    cin >> x >> y;

    cpp_int left = power(cpp_int(x), y);
    cpp_int right = power(cpp_int(y), x);

    if (left > right)
        cout << ">\n";
    else if (left < right)
        cout << "<\n";
    else
        cout << "=\n";

    return 0;
}

